import*as SDK from"../../../core/sdk/sdk.js";export function getTargetName(e){return SDK.TargetManager.TargetManager.instance().primaryPageTarget()===e||"main"===e.id()?"main":e.inspectedURL()}export function getTargetFrameContext(e,t){const o=[];for(;t;){const e=t.sameTargetParentFrame();if(!e)break;const n=e.childFrames.indexOf(t);o.unshift(n),t=e}return{target:getTargetName(e),frame:o}}export async function evaluateInAllFrames(e,t,o){const n=t.model(SDK.RuntimeModel.RuntimeModel).executionContexts(),r=t.model(SDK.ResourceTreeModel.ResourceTreeModel);for(const a of r.frames()){if(!n.find((e=>e.frameId===a.id)))continue;const{executionContextId:r}=await t.pageAgent().invoke_createIsolatedWorld({frameId:a.id,worldName:e});await t.runtimeAgent().invoke_evaluate({expression:o,includeCommandLineAPI:!0,contextId:r})}}export function findTargetByExecutionContext(e,t){for(const o of e){const e=o.model(SDK.RuntimeModel.RuntimeModel);if(e)for(const n of e.executionContexts())if(n.id===t)return o}}export function findFrameIdByExecutionContext(e,t){for(const o of e){const e=o.model(SDK.RuntimeModel.RuntimeModel);if(e)for(const o of e.executionContexts())if(o.id===t&&void 0!==o.frameId)return o.frameId}}export const isFrameTargetInfo=e=>"page"===e.type||"iframe"===e.type;